const pipeline = (x) => x();

const importers = [
  async (path) => {
    if (!/^\.[\\/](?:projects\/chartgpu-angular\/\.storybook\/stories(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.(ts|mdx))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(47);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?!.*node_modules)(?:\/projects\/chartgpu-angular\/\.storybook\/stories(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.(ts|mdx))$/ */
      './projects/chartgpu-angular/.storybook/stories/' + pathRemainder
    );
  }
  
];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}